 public MainViewModel(Store store,ImportService importer,AgentService agent){Store=store;Importer=importer;Agent=agent;Nav=new Command(p=>Navigate(p?.ToString()??"Dashboard"),()=>!Busy);Upload=new Command(async _=>await Browse(),()=>!Busy);Import=new Command(async _=>await ImportSelected(),()=>!Busy&&File.Exists(FilePath));Cancel=new Command(_=>cancel?.Cancel());Apply=new Command(_=>{page=0;LoadCandidates();},()=>!Busy);Next=new Command(_=>{if((page+1)*PageSize<Matched){page++;LoadCandidates();}},()=>!Busy);Previous=new Command(_=>{if(page>0){page--;LoadCandidates();}},()=>!Busy);Export=new Command(async _=>await ExportCurrent(),()=>!Busy&&Store.ActiveBatch>0);Send=new Command(async _=>await SendChat(),()=>!Busy&&!string.IsNullOrWhiteSpace(Prompt));Sample=new Command(async _=>await LoadSample(),()=>!Busy);SaveSettings=new Command(_=>Save());Prepared=new Command(_=>{if(Agent.PreparedReport is {} f){SetFilter(f);Heading="Prepared report · review filters";PageIndex=2;}},()=>!Busy);SelectBatch=new Command(_=>{if(SelectedBatch!=null){Store.ActiveBatch=SelectedBatch.Id;Agent.Reset();Refresh();Navigate("Dashboard");}},()=>!Busy);DeleteBatch=new Command(_=>Delete(),()=>!Busy&&Store.ActiveBatch>0);Refresh();agent.ToolExecuted+=name=>Application.Current.Dispatcher.Invoke(()=>{Activity="Agent tool: "+name;Logs=new(Store.Logs());});}
