 public string StatusFilter{get;set;}="";public string Search{get;set;}="";public string RoleFilter{get;set;}="";public string LocationFilter{get;set;}="";public string FindingFilter{get;set;}="";public string Sort{get;set;}="SourceRow";public bool Desc{get;set;}
