 public string MappingNotice=>"An overall-result column is optional. Leave it blank to classify screening checks: STOP/Hard Stop takes priority, then REVIEW, then all-PASS. Blank/unknown checks go to REVIEW. Personal fields are excluded. A mapped overall result takes precedence. Preview shows 6 source rows.";
 public string Endpoint{get;set;}="";public string Model{get;set;}="";public string ApiKey{get;set;}="";public bool AllowExternal{get;set;}public bool AllowExports{get;set;}public bool MaskPersonal{get;set;}public int TimeoutSeconds{get;set;}=90;
 public void Navigate(string target){Heading=target=="STOP Candidates"?"Reject candidates (STOP)":target;PageIndex=target switch{"Dashboard"=>0,"Upload Excel"=>1,"AI Analysis Center"=>3,"AI Agent Chat"=>4,"Reports"=>5,"Upload History"=>6,"Settings"=>7,_=>2};if(PageIndex==2){StatusFilter=target switch{"PASS Candidates"=>"PASS","REVIEW Candidates"=>"REVIEW","STOP Candidates"=>"STOP","Unclassified Records"=>"UNCLASSIFIED",_=>""};Search=RoleFilter=LocationFilter=FindingFilter=SourceColumnFilter=SourceTextFilter="";Changed(nameof(SourceColumnFilter));Changed(nameof(SourceTextFilter));page=0;Changed(nameof(StatusFilter));Changed(nameof(Search));Changed(nameof(RoleFilter));Changed(nameof(LocationFilter));Changed(nameof(FindingFilter));LoadCandidates();}if(PageIndex==0)Heading="Candidate Screening Intelligence Overview";if(PageIndex==3){Findings=new(Store.Findings());Logs=new(Store.Logs());}}
 public void SetFilter(Filter f){SourceColumnFilter=f.SourceColumn;SourceTextFilter=f.SourceText;Changed(nameof(SourceColumnFilter));Changed(nameof(SourceTextFilter));StatusFilter=f.Status;Search=f.Search;RoleFilter=f.Role;LocationFilter=f.Location;FindingFilter=f.Finding;Sort=f.Sort;Desc=f.Desc;page=0;foreach(var n in new[]{nameof(StatusFilter),nameof(Search),nameof(RoleFilter),nameof(LocationFilter),nameof(FindingFilter),nameof(Sort),nameof(Desc)})Changed(n);LoadCandidates();}
 public void LoadCandidates(){Matched=Store.Count(CurrentFilter);if(page*PageSize>=Matched)page=0;var rows=Store.Query(CurrentFilter,page*PageSize,PageSize);if(Store.ReadSettings().MaskPersonal)rows=rows.Select(c=>c with{Name=c.Name.Length>0?c.Name[..1]+"•••":"[missing]"}).ToList();Candidates=new(rows);Changed(nameof(PageLabel));}
 public void Refresh()
 {
  var s=Store.ReadSettings();Endpoint=s.Endpoint;Model=s.Model;AllowExternal=s.AllowExternal;AllowExports=s.AllowExports;MaskPersonal=s.MaskPersonal;TimeoutSeconds=s.TimeoutSeconds;History=new(Store.History());Quality=new(Store.FindingCounts());Findings=new(Store.Findings());Logs=new(Store.Logs());
  var colors=new[]{"#16A34A","#F59E0B","#DC2626","#64748B"};var statusNames=new[]{"PASS","REVIEW","STOP","UNCLASSIFIED"};var counts=Store.Counts().ToDictionary(x=>x.Name,x=>x.Count);StatusSeries=statusNames.Select((name,i)=>(ISeries)new PieSeries<long>{Name=name=="STOP"?"REJECT (STOP)":name,Values=[counts.GetValueOrDefault(name)],InnerRadius=68,Fill=new SolidColorPaint(SKColor.Parse(colors[i]))}).ToArray();
  ComparisonSeries=[new ColumnSeries<long>{Name="Source records",Values=statusNames.Select(x=>counts.GetValueOrDefault(x)).ToArray(),Fill=new SolidColorPaint(SKColor.Parse("#2563EB"))}];StatusAxes=[new Axis{Labels=statusNames,TextSize=10}];
  var roles=Store.Counts("Role").Take(8).ToList();RoleSeries=[new RowSeries<long>{Name="Records",Values=roles.Select(x=>x.Count).ToArray(),Fill=new SolidColorPaint(SKColor.Parse("#2563EB"))}];RoleAxes=[new Axis{Labels=roles.Select(x=>x.Name==""?"Not supplied":x.Name).ToArray(),TextSize=11}];
  var locations=Store.Counts("Location").Take(10).ToList();LocationSeries=statusNames.Select((n,i)=>(ISeries)new StackedColumnSeries<long>{Name=n,Values=locations.Select(l=>Store.Count(new(Status:n,Location:l.Name))).ToArray(),Fill=new SolidColorPaint(SKColor.Parse(colors[i]))}).ToArray();LocationAxes=[new Axis{Labels=locations.Select(x=>x.Name==""?"Not supplied":x.Name).ToArray(),TextSize=10}];
  long missing=Store.Count(new(Finding:"Missing verification")),pending=Store.Count(new(Finding:"Pending verification"));CompletenessSeries=[new ColumnSeries<long>{Name="Records (may overlap)",Values=[missing,pending],Fill=new SolidColorPaint(SKColor.Parse("#0D9488"))}];
  foreach(var n in new[]{nameof(Total),nameof(Pass),nameof(Review),nameof(Stop),nameof(Unclassified),nameof(PassPercent),nameof(ReviewPercent),nameof(StopPercent),nameof(UnclassifiedPercent),nameof(Summary),nameof(DataNotice),nameof(ActiveFile),nameof(AgentStatus),nameof(Roles),nameof(Locations),nameof(SourceColumns),nameof(StatusSeries),nameof(ComparisonSeries),nameof(StatusAxes),nameof(RoleSeries),nameof(RoleAxes),nameof(LocationSeries),nameof(LocationAxes),nameof(CompletenessSeries),nameof(Endpoint),nameof(Model),nameof(AllowExternal),nameof(AllowExports),nameof(MaskPersonal),nameof(TimeoutSeconds)})Changed(n);LoadCandidates();
 }
 public async Task Work(Func<CancellationToken,Task> action){if(Busy)return;Busy=true;cancel=new();try{await action(cancel.Token);}catch(OperationCanceledException){Activity="Operation cancelled. No partial import or export was committed.";}catch(Exception ex){Serilog.Log.Error(ex,"Operation failed");Activity="Error: "+ex.Message;MessageBox.Show(ex.Message,"AccurateHire IQ",MessageBoxButton.OK,MessageBoxImage.Warning);}finally{Busy=false;cancel.Dispose();cancel=null;}}
 public async Task Browse(){var d=new OpenFileDialog{Filter="Candidate data|*.xlsx;*.xls;*.csv",Title="Import candidate screening data"};if(d.ShowDialog()==true)await PreviewFile(d.FileName);}
 public async Task PreviewFile(string path){await Work(async ct=>{Activity="Reading workbook preview…";var data=await Task.Run(()=>{var sheets=Importer.Sheets(path);return(sheets,preview:Importer.Preview(path));},ct);FilePath=path;Sheets=data.sheets;SelectedSheet=data.preview.Sheet;SetPreview(data.preview);PageIndex=1;Heading="Upload Excel";Changed(nameof(Sheets));Changed(nameof(SelectedSheet));Activity="Preview ready. Confirm column mapping, then import.";});}
 public async Task ChangeSheet(){if(File.Exists(FilePath)&&SelectedSheet!="")await Work(async ct=>{var p=await Task.Run(()=>Importer.Preview(FilePath,SelectedSheet),ct);SetPreview(p);});}
 void SetPreview(Preview p){Columns=new[]{""}.Concat(p.Headers).ToList();var m=ImportService.Guess(p.Headers);IdColumn=m.Id;NameColumn=m.Name;StatusColumn=m.Status;RoleColumn=m.Role;LocationColumn=m.Location;RemarksColumn=m.Remarks;var table=new DataTable();foreach(var h in p.Headers)table.Columns.Add(h);foreach(var r in p.Rows)table.Rows.Add(p.Headers.Select(h=>(object)r[h]).ToArray());PreviewRows=table.DefaultView;foreach(var n in new[]{nameof(Columns),nameof(IdColumn),nameof(NameColumn),nameof(StatusColumn),nameof(RoleColumn),nameof(LocationColumn),nameof(RemarksColumn),nameof(PreviewRows)})Changed(n);}
 public async Task ImportSelected(){await Work(async ct=>{var m=new Mapping(IdColumn,NameColumn,StatusColumn,RoleColumn,LocationColumn,RemarksColumn);var progress=new Progress<string>(s=>Activity=s);Activity="Importing source records…";long n=await Task.Run(()=>Importer.Import(FilePath,m,SelectedSheet,progress,ct),ct);Agent.Reset();Refresh();Navigate("Dashboard");Activity=$"Imported {n:N0} records. Source values preserved.";});}
 public async Task LoadSample(){var path=Path.Combine(AppContext.BaseDirectory,"Data","Sample.xlsx");await PreviewFile(path);if(!Busy&&FilePath==path)await ImportSelected();}
 public async Task ExportCurrent(bool analysis=false){if(!Store.ReadSettings().AllowExports){MessageBox.Show("Exports are disabled in Settings.");return;}var d=new SaveFileDialog{Filter=analysis?"Excel workbook|*.xlsx":"Excel workbook|*.xlsx|CSV file|*.csv",FileName=$"{(analysis?"Operational_Analysis":StatusFilter==""?"All":StatusFilter)}_Candidates_{DateTime.Now:yyyy-MM-dd}.xlsx"};if(d.ShowDialog()!=true)return;var f=analysis?new Filter():CurrentFilter;await Work(async ct=>{var progress=new Progress<string>(s=>Activity=s);long n=await Task.Run(()=>Importer.Export(d.FileName,f,progress,ct,analysis),ct);Activity=$"Saved {n:N0} candidate records to {d.FileName}";Logs=new(Store.Logs());});}
 async Task SendChat(){string q=Prompt.Trim();if(q=="")return;Prompt="";Conversation+="\n\nYOU\n"+q;await Work(async ct=>{Activity="Agent is querying the active dataset…";try{var answer=await Agent.Ask(q,ct);Conversation+="\n\nACCURATEHIRE INTELLIGENCE AGENT · AI-GENERATED\n"+answer;Activity="Agent response ready. Check source references before acting.";}catch(Exception e){Conversation+="\n\nSYSTEM\n"+e.Message;throw;}finally{Logs=new(Store.Logs());}});}
 void Save(){try{if(!Uri.TryCreate(Endpoint,UriKind.Absolute,out var u)||!(u.Scheme=="https"||(u.Scheme=="http"&&u.IsLoopback)))throw new InvalidOperationException("Use HTTPS, or HTTP for localhost.");var old=Store.ReadSettings();Store.SaveSettings(new(){Endpoint=Endpoint.Trim(),Model=Model.Trim(),ProtectedKey=ApiKey==""?old.ProtectedKey:AgentService.Protect(ApiKey),AllowExternal=AllowExternal,AllowExports=AllowExports,MaskPersonal=MaskPersonal,TimeoutSeconds=Math.Clamp(TimeoutSeconds,15,180)});ApiKey="";Agent.Reset();Refresh();Activity="Settings saved. API key protected for this Windows user.";}catch(Exception ex){MessageBox.Show(ex.Message,"Settings");}}
 void Delete(){if(MessageBox.Show("Delete the active batch, its original records, findings and execution history? Previously exported files are not removed.","Delete local batch",MessageBoxButton.YesNo,MessageBoxImage.Warning)!=MessageBoxResult.Yes)return;Store.DeleteActive();Agent.Reset();Refresh();Activity="Active batch deleted from the local database.";}
}
